#include <iostream>
#include <vector>
#include <atcoder/segtree>

using namespace std;

constexpr int INF = 100000000;

// 区間最大値を得るセグメント木の準備
using S = int;
int op(int a, int b) { return max(a, b); }
int e() { return -INF; }
using segtree = atcoder::segtree<S, op, e>;

void calc(const int N, const vector<int> &P, vector<int> &D) {
    // chmin(D[i], P[i] + i - max_{j < i && P[j] < P[i]} {P[j] + j}
    segtree segment_tree(N);
    for (int i = 0; i < N; ++i) {
        D[i] = min(D[i], P[i] + i - segment_tree.prod(0, P[i]));
        segment_tree.set(P[i] - 1, P[i] + i);
    }
}

int main() {

    int N;
    cin >> N;
    vector<int> P(N);
    for (auto &&p : P) cin >> p;
    vector<int> D(N, INF);

    // j < i かつ P[j] < P[i] なる j について計算
    calc(N, P, D);

    // j < i かつ P[j] > P[i]
    for (auto &&p : P) p = N + 1 - p;
    calc(N, P, D);

    // j > i かつ P[j] > P[i]
    reverse(begin(P), end(P));
    reverse(begin(D), end(D));
    calc(N, P, D);

    // j > i かつ P[j] < P[i]
    for (auto &&p : P) p = N + 1 - p;
    calc(N, P, D);

    // 反転を直して出力
    reverse(begin(P), end(P));
    reverse(begin(D), end(D));
    for (int i = 0; i < N; ++i) cout << D[i] << " ";
    cout << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <limits>
#include <set>
#include <utility>
#include <algorithm>

int main() {
    using namespace std;

    unsigned long N;
    cin >> N;
    vector<unsigned long> P(N);
    for(auto&& p : P)cin >> p;
    vector<unsigned long> D(N, numeric_limits<unsigned long>::max());

    const auto calc{[&P, &N, &D]{
        // chmin(D[i], min_{j < i && P[j] < P[i]} (P[i] + i) - (P[j] + j)); (i = 1, 2, ..., N)
        // を O(N log N) 時間で実行

        // 最小値を与える可能性がある j を P[j] の昇順に管理
        set<pair<unsigned long, unsigned long>> cost_set;

        for(unsigned long i{}; i < N; ++i){
            const auto value{P[i]};
            const auto cost{P[i] + i};

            // D[i] を更新
            auto it{cost_set.upper_bound({P[i], 0})};
            if(it != begin(cost_set))D[i] = min(D[i], cost - prev(it) -> second);

            // j の候補を更新
            while(it != end(cost_set) && it -> second <= cost)it = cost_set.erase(it);
            cost_set.emplace_hint(it, value, cost);
        }
    }};

    // j < i かつ P[j] < P[i] なる j について計算
    calc();

    // j < i かつ P[j] > P[i]
    for(auto&& p : P)p = N - p;
    calc();

    // j > i かつ P[j] > P[i]
    reverse(begin(P), end(P));
    reverse(begin(D), end(D));
    calc();

    // j > i かつ P[j] < P[i]
    for(auto&& p : P)p = N - p;
    calc();

    // 反転しているので逆順に出力
    for(unsigned long i{N}; i--; )cout << D[i] << (i ? ' ' : '\n');

    return 0;
}
